require('dotenv').config();
const fs=require('fs'),path=require('path');
const express=require('express'),cors=require('cors'),bcrypt=require('bcryptjs'),jwt=require('jsonwebtoken'),crypto=require('crypto'),helmet=require('helmet'),rateLimit=require('express-rate-limit'),nodemailer=require('nodemailer');
const Database=require('better-sqlite3');
const DB_PATH=process.env.DB_PATH||'avrixon.db';
const dbDir=path.dirname(path.resolve(DB_PATH));
fs.mkdirSync(dbDir,{recursive:true});
const db=new Database(DB_PATH); db.pragma('journal_mode=WAL'); db.pragma('foreign_keys=ON');

db.exec(`
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT UNIQUE,password_hash TEXT NOT NULL,balance REAL DEFAULT 0,referral_code TEXT UNIQUE NOT NULL,referred_by INTEGER,active INTEGER DEFAULT 1,device_id TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT DEFAULT 'admin',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,method TEXT NOT NULL,account TEXT NOT NULL,label TEXT,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deposits(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,method TEXT NOT NULL,amount REAL NOT NULL,sender_account TEXT NOT NULL,transaction_id TEXT NOT NULL UNIQUE,status TEXT DEFAULT 'pending',admin_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,verified_at TEXT);
CREATE TABLE IF NOT EXISTS withdrawals(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,method TEXT NOT NULL,account TEXT NOT NULL,amount REAL NOT NULL,status TEXT DEFAULT 'pending',transaction_id TEXT UNIQUE,admin_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,reward REAL NOT NULL,status TEXT DEFAULT 'active',task_type TEXT DEFAULT 'public',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS task_submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,task_id INTEGER NOT NULL,proof TEXT,status TEXT DEFAULT 'pending',reward REAL NOT NULL,admin_note TEXT,verified_at TEXT,verified_by TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,task_id));
CREATE TABLE IF NOT EXISTS earnings(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,type TEXT NOT NULL,source_id INTEGER,amount REAL NOT NULL,status TEXT DEFAULT 'credited',description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallet_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,type TEXT NOT NULL,source_id INTEGER,amount REAL NOT NULL,direction TEXT NOT NULL,balance_after REAL NOT NULL,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS referral_rewards(id INTEGER PRIMARY KEY AUTOINCREMENT,referrer_id INTEGER NOT NULL,referred_user_id INTEGER NOT NULL,source_submission_id INTEGER NOT NULL UNIQUE,amount REAL NOT NULL,status TEXT DEFAULT 'credited',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS referral_signup_rewards(id INTEGER PRIMARY KEY AUTOINCREMENT,referrer_id INTEGER NOT NULL,referred_user_id INTEGER NOT NULL UNIQUE,referrer_amount REAL NOT NULL,new_user_amount REAL NOT NULL,status TEXT DEFAULT 'credited',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advertisers(id INTEGER PRIMARY KEY AUTOINCREMENT,business_name TEXT NOT NULL,owner_name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,balance REAL DEFAULT 0,status TEXT DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advertiser_deposits(id INTEGER PRIMARY KEY AUTOINCREMENT,advertiser_id INTEGER NOT NULL,method TEXT NOT NULL,amount REAL NOT NULL,sender_account TEXT NOT NULL,transaction_id TEXT NOT NULL UNIQUE,status TEXT DEFAULT 'pending',admin_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,verified_at TEXT);
CREATE TABLE IF NOT EXISTS advertiser_wallet_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,advertiser_id INTEGER NOT NULL,type TEXT NOT NULL,source_id INTEGER,amount REAL NOT NULL,direction TEXT NOT NULL,balance_after REAL NOT NULL,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campaigns(id INTEGER PRIMARY KEY AUTOINCREMENT,advertiser_id INTEGER NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,total_budget REAL NOT NULL,reward_per_completion REAL NOT NULL,platform_fee REAL DEFAULT 0,remaining_budget REAL DEFAULT 0,status TEXT DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campaign_tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,campaign_id INTEGER NOT NULL,task_id INTEGER NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER,action TEXT NOT NULL,target_type TEXT,target_id INTEGER,details TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
`);

