const SECRET=process.env.JWT_SECRET||'CHANGE_ME_IN_PRODUCTION';
if(process.env.NODE_ENV==='production' && (!process.env.JWT_SECRET || SECRET.length<32 || SECRET==='CHANGE_ME_IN_PRODUCTION')) throw new Error('JWT_SECRET must be set to a strong 32+ character secret in production');
if(process.env.NODE_ENV==='production' && !process.env.ADMIN_PASSWORD) throw new Error('ADMIN_PASSWORD must be set in production');
