const EMAIL_FROM=process.env.EMAIL_FROM||process.env.SMTP_USER||'';
const smtpTransport=(process.env.SMTP_HOST&&process.env.SMTP_USER&&process.env.SMTP_PASS)?nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:String(process.env.SMTP_SECURE||'false')==='true',auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}}):null;
const resendKey=process.env.RESEND_API_KEY||'';
async function sendVerificationEmail(to,code){
  const subject='AVRIXON — Email Verification Code';
  const text=`আপনার AVRIXON email verification code: ${code}\n\nএই কোডটি 10 মিনিটের মধ্যে ব্যবহার করুন।`;
  if(smtpTransport){await smtpTransport.sendMail({from:EMAIL_FROM||process.env.SMTP_USER,to,subject,text,html:`<div style="font-family:Arial,sans-serif"><h2>AVRIXON Email Verification</h2><p>আপনার verification code:</p><div style="font-size:30px;font-weight:800;letter-spacing:8px">${code}</div><p>এই কোডটি 10 মিনিটের মধ্যে ব্যবহার করুন।</p></div>`});return;}
  if(resendKey){const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Authorization':`Bearer ${resendKey}`,'Content-Type':'application/json'},body:JSON.stringify({from:EMAIL_FROM||'AVRIXON <onboarding@resend.dev>',to:[to],subject,html:`<h2>AVRIXON Email Verification</h2><p>আপনার verification code:</p><h1>${code}</h1><p>এই কোডটি 10 মিনিটের মধ্যে ব্যবহার করুন।</p>`})});if(!r.ok)throw Error('Email service failed');return;}
  if(process.env.NODE_ENV!=='production')return;
  throw Error('Email service is not configured');
}
// Temporary user deposit configuration: bKash/Nagad Send Money only.
for (const method of ['bkash','nagad']) {
  const exists=db.prepare('SELECT id FROM payment_accounts WHERE method=? AND account=?').get(method,USER_DEPOSIT_NUMBER);
  if(!exists) db.prepare("INSERT INTO payment_accounts(method,account,label,active) VALUES(?,?,?,1)").run(method,USER_DEPOSIT_NUMBER,'AVRIXON User Deposit - Send Money Only');
}

function validAmount(n){return Number.isFinite(n)&&n>0&&n<=1000000&&Math.abs(n*100-Math.round(n*100))<1e-9}
function validBdAccount(x){return /^01[3-9]\d{8}$/.test(cleanPhone(x))}
function cleanEmail(x){return String(x||'').trim().toLowerCase()}
function auth(req,res,next){try{const h=req.headers.authorization||'';if(!h.startsWith('Bearer '))throw 0;const p=jwt.verify(h.slice(7),SECRET);if(p.role&&p.role!=='user')throw 0;const u=db.prepare('SELECT id,name,phone,balance,referral_code,active,device_id FROM users WHERE id=?').get(p.id);if(!u||!u.active)throw 0;const deviceId=String(req.headers['x-device-id']||'').trim();if(u.device_id && u.device_id!==deviceId)throw Object.assign(new Error('device mismatch'),{code:'DEVICE_MISMATCH'});req.user=p;next()}catch(e){res.status(401).json({error:e.code==='DEVICE_MISMATCH'?'এই অ্যাকাউন্টটি অন্য একটি ডিভাইসের সাথে যুক্ত। একই ডিভাইস ব্যবহার করুন।':'Authentication required'})}}
function advertiserAuth(req,res,next){try{const h=req.headers.authorization||'';if(!h.startsWith('Bearer '))throw 0;const p=jwt.verify(h.slice(7),SECRET);if(p.role!=='advertiser')throw 0;req.advertiser=p;next()}catch{res.status(401).json({error:'Advertiser authentication required'})}}
function adminAuth(req,res,next){try{const h=req.headers.authorization||'';if(!h.startsWith('Bearer '))throw 0;const p=jwt.verify(h.slice(7),SECRET);if(p.role!=='admin')throw 0;const a=db.prepare('SELECT id,name,email,role,active FROM admin_users WHERE id=?').get(p.id);if(!a||!a.active)throw 0;req.admin=a;next()}catch{res.status(401).json({error:'Admin authentication required'})}}
function sign(payload){return jwt.sign(payload,SECRET,{expiresIn:'7d'})}
function addUserLedger(userId,type,sourceId,amount,direction,description){const u=db.prepare('SELECT balance FROM users WHERE id=?').get(userId);if(!u)throw Error('User not found');const next=direction==='credit'?u.balance+amount:u.balance-amount;if(next< -0.000001)throw Error('Insufficient balance');db.prepare('UPDATE users SET balance=? WHERE id=?').run(next,userId);db.prepare('INSERT INTO wallet_transactions(user_id,type,source_id,amount,direction,balance_after,description) VALUES(?,?,?,?,?,?,?)').run(userId,type,sourceId,amount,direction,next,description);return next}
function addAdvertiserLedger(advertiserId,type,sourceId,amount,direction,description){const a=db.prepare('SELECT balance FROM advertisers WHERE id=?').get(advertiserId);if(!a)throw Error('Advertiser not found');const next=direction==='credit'?a.balance+amount:a.balance-amount;if(next< -0.000001)throw Error('Insufficient advertiser balance');db.prepare('UPDATE advertisers SET balance=? WHERE id=?').run(next,advertiserId);db.prepare('INSERT INTO advertiser_wallet_transactions(advertiser_id,type,source_id,amount,direction,balance_after,description) VALUES(?,?,?,?,?,?,?)').run(advertiserId,type,sourceId,amount,direction,next,description);return next}
function audit(adminId,action,targetType,targetId,details){db.prepare('INSERT INTO audit_logs(admin_id,action,target_type,target_id,details) VALUES(?,?,?,?,?)').run(adminId,action,targetType,targetId,details||'')}

