// User auth
function cleanPhone(x){let v=String(x||'').replace(/\s|-/g,''); if(v.startsWith('+880')) v='0'+v.slice(4); if(v.startsWith('880')) v='0'+v.slice(3); return v}
function validPhone(x){return /^01[3-9]\d{8}$/.test(cleanPhone(x))}
app.post('/api/auth/register',async(req,res)=>{const{phone,password,referralCode}=req.body||{},p=cleanPhone(phone),deviceId=String(req.body?.deviceId||'').trim();if(!validPhone(p)||!password||String(password).length<6||String(password).length>128)return res.status(400).json({error:'সঠিক বাংলাদেশি মোবাইল নম্বর এবং ৬–১২৮ অক্ষরের পাসওয়ার্ড দিন'});if(!/^[A-Za-z0-9._:-]{16,128}$/.test(deviceId))return res.status(400).json({error:'ডিভাইস শনাক্তকরণ তথ্য পাওয়া যায়নি। আবার চেষ্টা করুন।'});try{if(db.prepare('SELECT id FROM users WHERE device_id=?').get(deviceId))return res.status(409).json({error:'এই ডিভাইস থেকে ইতিমধ্যে একটি User account খোলা হয়েছে।'});const h=await bcrypt.hash(String(password),12);let referrer=null;if(referralCode){referrer=db.prepare('SELECT id FROM users WHERE referral_code=? AND active=1').get(String(referralCode).trim().toUpperCase());if(!referrer)return res.status(400).json({error:'রেফার কোডটি সঠিক নয়'});}let c;for(let i=0;i<5;i++){c='AVX-'+crypto.randomBytes(5).toString('hex').toUpperCase();if(!db.prepare('SELECT id FROM users WHERE referral_code=?').get(c))break}const syntheticEmail=p+'@phone.avrixon.local';const result=db.transaction(()=>{const r=db.prepare('INSERT INTO users(name,email,phone,password_hash,referral_code,referred_by,device_id) VALUES(?,?,?,?,?,?,?)').run('AVRIXON User',syntheticEmail,p,h,c,referrer?.id||null,deviceId);const userId=Number(r.lastInsertRowid);addUserLedger(userId,'welcome_bonus',userId,80,'credit','নতুন অ্যাকাউন্ট খোলার স্বাগত বোনাস');db.prepare('INSERT INTO earnings(user_id,type,source_id,amount,description) VALUES(?,?,?,?,?)').run(userId,'welcome_bonus',userId,80,'নতুন অ্যাকাউন্ট খোলার স্বাগত বোনাস');let referralBonus=0;if(referrer){referralBonus=25;addUserLedger(referrer.id,'referral_signup',userId,25,'credit','নতুন সদস্য রেফার করার বোনাস');db.prepare('INSERT INTO earnings(user_id,type,source_id,amount,description) VALUES(?,?,?,?,?)').run(referrer.id,'referral_signup',userId,25,'নতুন সদস্য রেফার করার বোনাস');db.prepare('INSERT INTO referral_signup_rewards(referrer_id,referred_user_id,referrer_amount,new_user_amount) VALUES(?,?,?,?)').run(referrer.id,userId,25,80)}return {user:db.prepare('SELECT id,name,phone,balance,referral_code FROM users WHERE id=?').get(userId),referralBonus}})();res.status(201).json({user:result.user,token:sign({id:result.user.id,phone:result.user.phone,role:'user'}),welcomeBonus:80,referralBonus:result.referralBonus,referralApplied:!!referrer,message:referrer?'অভিনন্দন! আপনার অ্যাকাউন্টে ৳৮০ স্বাগত বোনাস এবং রেফার করা ব্যক্তির জন্য ৳২৫ রেফার বোনাস দেওয়া হয়েছে।':'অভিনন্দন! আপনার অ্যাকাউন্টে ৳৮০ স্বাগত বোনাস যোগ হয়েছে।'})}catch(e){if(String(e.message||'').includes('UNIQUE'))return res.status(409).json({error:'এই মোবাইল নম্বরটি আগে থেকেই নিবন্ধিত'});console.error(e);res.status(500).json({error:'অ্যাকাউন্ট তৈরি করা যায়নি'})}});
app.post('/api/auth/login',async(req,res)=>{const p=cleanPhone(req.body?.phone),deviceId=String(req.body?.deviceId||'').trim();const u=db.prepare('SELECT * FROM users WHERE phone=?').get(p);if(!u||!u.active||!(await bcrypt.compare(req.body?.password||'',u.password_hash)))return res.status(401).json({error:'Invalid mobile number or password'});if(!/^[A-Za-z0-9._:-]{16,128}$/.test(deviceId))return res.status(400).json({error:'ডিভাইস শনাক্তকরণ তথ্য পাওয়া যায়নি।'});if(u.device_id && u.device_id!==deviceId)return res.status(403).json({error:'এই User account অন্য একটি ডিভাইসের সাথে যুক্ত। একই ডিভাইস থেকে Login করুন।'});if(!u.device_id)db.prepare('UPDATE users SET device_id=? WHERE id=?').run(deviceId,u.id);res.json({user:{id:u.id,name:u.name,phone:u.phone,balance:u.balance,referral_code:u.referral_code},token:sign({id:u.id,phone:u.phone,role:'user'})})});
app.get('/api/me',auth,(req,res)=>{const u=db.prepare('SELECT id,name,phone,email,profile_image,email_verified,balance,referral_code,created_at FROM users WHERE id=?').get(req.user.id);if(!u)return res.status(404).json({error:'User not found'});res.json(u)});
app.put('/api/profile',auth,(req,res)=>{const{name,email,profileImage}=req.body||{};const cleanName=String(name||'').trim();const clean=cleanEmail(email);if(cleanName && (cleanName.length<2||cleanName.length>80))return res.status(400).json({error:'নাম ২ থেকে ৮০ অক্ষরের মধ্যে হতে হবে'});if(clean && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean))return res.status(400).json({error:'সঠিক email address দিন'});if(profileImage!==undefined && profileImage!==null && profileImage!=='' && (!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(String(profileImage)) || String(profileImage).length>900000))return res.status(400).json({error:'ছবিটি JPG, PNG বা WEBP হতে হবে এবং 700KB-এর মধ্যে হতে হবে'});try{const u=db.prepare('SELECT name,email FROM users WHERE id=?').get(req.user.id);const nextName=cleanName||u.name;let nextEmail=u.email;let changedEmail=false;if(clean){if(clean.endsWith('@phone.avrixon.local')) changedEmail=true; else if(clean!==u.email) changedEmail=true; nextEmail=clean;}db.prepare('UPDATE users SET name=?,email=?,profile_image=COALESCE(?,profile_image),email_verified=CASE WHEN ? THEN 0 ELSE email_verified END,email_verification_hash=CASE WHEN ? THEN NULL ELSE email_verification_hash END,email_verification_expires=CASE WHEN ? THEN NULL ELSE email_verification_expires END WHERE id=?').run(nextName,nextEmail,profileImage||null,changedEmail?1:0,changedEmail?1:0,changedEmail?1:0,req.user.id);res.json(db.prepare('SELECT id,name,phone,email,profile_image,email_verified,balance,referral_code,created_at FROM users WHERE id=?').get(req.user.id));}catch(e){if(String(e.message||'').includes('UNIQUE'))return res.status(409).json({error:'এই email address ইতিমধ্যে ব্যবহার করা হয়েছে'});res.status(400).json({error:e.message})}});
app.post('/api/profile/email/request',auth,async(req,res)=>{const email=cleanEmail(req.body?.email);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return res.status(400).json({error:'সঠিক email address দিন'});const exists=db.prepare('SELECT id FROM users WHERE email=? AND id<>?').get(email,req.user.id);if(exists)return res.status(409).json({error:'এই email address ইতিমধ্যে ব্যবহার করা হয়েছে'});const code=String(crypto.randomInt(100000,1000000));const hash=crypto.createHash('sha256').update(code).digest('hex');const expires=new Date(Date.now()+10*60*1000).toISOString();db.prepare('UPDATE users SET email=?,email_verified=0,email_verification_hash=?,email_verification_expires=? WHERE id=?').run(email,hash,expires,req.user.id);try{await sendVerificationEmail(email,code);const out={message:'Verification code আপনার email-এ পাঠানো হয়েছে।'};if(process.env.NODE_ENV!=='production'&&!smtpTransport&&!resendKey)out.devCode=code;res.json(out);}catch(e){db.prepare('UPDATE users SET email_verification_hash=NULL,email_verification_expires=NULL WHERE id=?').run(req.user.id);res.status(503).json({error:e.message})}});
app.post('/api/profile/email/verify',auth,(req,res)=>{const code=String(req.body?.code||'').trim();if(!/^\d{6}$/.test(code))return res.status(400).json({error:'৬ সংখ্যার verification code দিন'});const u=db.prepare('SELECT email,email_verification_hash,email_verification_expires FROM users WHERE id=?').get(req.user.id);if(!u?.email_verification_hash||!u.email_verification_expires)return res.status(400).json({error:'আগে verification code request করুন'});if(Date.now()>new Date(u.email_verification_expires).getTime())return res.status(400).json({error:'Verification code-এর মেয়াদ শেষ হয়েছে'});const hash=crypto.createHash('sha256').update(code).digest('hex');if(hash!==u.email_verification_hash)return res.status(400).json({error:'Verification code সঠিক নয়'});db.prepare('UPDATE users SET email_verified=1,email_verification_hash=NULL,email_verification_expires=NULL WHERE id=?').run(req.user.id);res.json({message:'Email সফলভাবে verified হয়েছে।',email:u.email});});
