app.post('/api/deposits',auth,(req,res)=>{const{method,senderAccount,transactionId}=req.body||{},n=USER_DEPOSIT_AMOUNT,tx=String(transactionId||'').trim();if(!['bkash','nagad'].includes(method)||!senderAccount||tx.length<4)return res.status(400).json({error:'Only bKash/Nagad Send Money is accepted. Deposit amount must be exactly ৳120.'});if(String(senderAccount).trim()===USER_DEPOSIT_NUMBER)return res.status(400).json({error:'Sender number must be your own bKash/Nagad number.'});if(!db.prepare('SELECT id FROM payment_accounts WHERE method=? AND account=? AND active=1').get(method,USER_DEPOSIT_NUMBER))return res.status(400).json({error:'User deposit account is not configured'});try{const r=db.prepare('INSERT INTO deposits(user_id,method,amount,sender_account,transaction_id) VALUES(?,?,?,?,?)').run(req.user.id,method,n,String(senderAccount).trim(),tx);res.status(201).json({id:r.lastInsertRowid,status:'pending',message:'৳120 Send Money payment submitted for manual verification'})}catch{res.status(409).json({error:'This transaction ID has already been submitted'})}});
app.get('/api/deposits',auth,(req,res)=>res.json(db.prepare('SELECT * FROM deposits WHERE user_id=? ORDER BY id DESC').all(req.user.id)));
app.post('/api/withdrawals',auth,(req,res)=>{const{method,account,amount}=req.body||{},n=Number(amount),acct=cleanPhone(account);if(!['bkash','nagad'].includes(method)||!validBdAccount(acct)||!validAmount(n))return res.status(400).json({error:'Enter a valid bKash/Nagad number and withdrawal amount'});if(n<MIN_WITHDRAWAL_AMOUNT)return res.status(400).json({error:`Minimum withdrawal amount is ৳${MIN_WITHDRAWAL_AMOUNT}.`});if(n>MAX_WITHDRAWAL_AMOUNT)return res.status(400).json({error:`Maximum withdrawal amount per transaction is ৳${MAX_WITHDRAWAL_AMOUNT}.`});try{const result=db.transaction(()=>{const u=db.prepare('SELECT balance,first_withdrawal_task_completed FROM users WHERE id=?').get(req.user.id);if(!u)throw Error('User not found');if(!u.first_withdrawal_task_completed){const approvedDeposit=!!db.prepare("SELECT id FROM deposits WHERE user_id=? AND status='approved' AND amount=? LIMIT 1").get(req.user.id,USER_DEPOSIT_AMOUNT);const referralCount=Number(db.prepare('SELECT COUNT(*) AS c FROM users WHERE referred_by=? AND active=1').get(req.user.id).c);const missing=[];if(!approvedDeposit)missing.push(`verified ৳${USER_DEPOSIT_AMOUNT} deposit`);if(referralCount<FIRST_WITHDRAWAL_REFERRAL_REQUIREMENT)missing.push(`${FIRST_WITHDRAWAL_REFERRAL_REQUIREMENT} valid referrals (${referralCount}/${FIRST_WITHDRAWAL_REFERRAL_REQUIREMENT})`);if(missing.length){const e=new Error(`Before your first withdrawal, complete the one-time withdrawal task: ${missing.join(' and ')}. It is shown only when you withdraw. Once both conditions are completed, it is completed for your lifetime and will never be required again—even if this or a later withdrawal is rejected.`);e.code='FIRST_WITHDRAWAL_TASK_REQUIRED';e.meta={referralCount,required:FIRST_WITHDRAWAL_REFERRAL_REQUIREMENT,depositAmount:USER_DEPOSIT_AMOUNT,approvedDeposit};throw e;}db.prepare('UPDATE users SET first_withdrawal_task_completed=1 WHERE id=?').run(req.user.id);}addUserLedger(req.user.id,'withdrawal',null,n,'debit','Withdrawal request reserved');return db.prepare('INSERT INTO withdrawals(user_id,method,account,amount) VALUES(?,?,?,?)').run(req.user.id,method,acct,n)})();res.status(201).json({id:result.lastInsertRowid,message:'Withdrawal request sent for manual agent payout'})}catch(e){if(e.code==='FIRST_WITHDRAWAL_TASK_REQUIRED')return res.status(400).json({error:e.message,code:e.code,...e.meta});res.status(400).json({error:e.message})}});
