app.get('/api/withdrawal-requirements',auth,(req,res)=>{const u=db.prepare('SELECT first_withdrawal_task_completed FROM users WHERE id=?').get(req.user.id);const approvedDeposit=!!db.prepare("SELECT id FROM deposits WHERE user_id=? AND status='approved' AND amount=? LIMIT 1").get(req.user.id,USER_DEPOSIT_AMOUNT);const referralCount=Number(db.prepare('SELECT COUNT(*) AS c FROM users WHERE referred_by=? AND active=1').get(req.user.id).c);const taskCompleted=!!u.first_withdrawal_task_completed;const taskVisible=!taskCompleted;res.json({minimumAmount:MIN_WITHDRAWAL_AMOUNT,maximumAmount:MAX_WITHDRAWAL_AMOUNT,firstWithdrawalTaskRequired:taskVisible,referralCount,requiredReferrals:FIRST_WITHDRAWAL_REFERRAL_REQUIREMENT,taskCompleted,approvedDeposit,depositAmount:USER_DEPOSIT_AMOUNT,oneTimeLifetimeTask:true})});
