app.get('/api/tasks',auth,(req,res)=>{const tasks=db.prepare(`SELECT t.*,s.id submission_id,s.status submission_status,s.admin_note submission_note FROM tasks t LEFT JOIN task_submissions s ON s.task_id=t.id AND s.user_id=? WHERE t.status='active' AND t.task_type='public' ORDER BY t.id DESC`).all(req.user.id);const businessOpportunity={title:'🏢 Business Account — নিজের প্রচার শুরু করুন',description:'আপনি যদি নিজের ব্যবসা, পণ্য, সেবা বা Campaign প্রচার করতে চান, আলাদা Business Account খুলে Campaign চালু করতে পারবেন। Business Account থেকে Campaign তৈরি, বাজেট জমা এবং Admin approval-এর মাধ্যমে আপনার প্রচারণা AVRIXON-এর User Task-এ প্রকাশ করা যায়।',category:'Business',reward:0,action_url:'/business',action_label:'Business Account খুলুন',is_business_opportunity:true};res.json({tasks,businessOpportunity})});
app.post('/api/tasks/:id/submit',auth,(req,res)=>{const t=db.prepare('SELECT * FROM tasks WHERE id=? AND status=\'active\'').get(req.params.id);if(!t)return res.status(404).json({error:'Task not found'});const proof=String(req.body?.proof||'').trim();const proofImage=String(req.body?.proofImage||'').trim();if(proof.length<3)return res.status(400).json({error:'কাজের প্রমাণ/বিস্তারিত দিন'});if(t.task_url && (!proofImage || !/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(proofImage) || proofImage.length>1400000))return res.status(400).json({error:'এই Facebook Task-এর জন্য Follow করার Screenshot আপলোড করা বাধ্যতামূলক। JPG/PNG/WEBP এবং সর্বোচ্চ 1MB ছবি দিন।'});try{const r=db.prepare('INSERT INTO task_submissions(user_id,task_id,proof,proof_image,reward) VALUES(?,?,?,?,?)').run(req.user.id,t.id,proof,proofImage||null,t.reward);res.status(201).json({id:r.lastInsertRowid,message:'কাজটি যাচাইয়ের জন্য জমা হয়েছে'})}catch{res.status(409).json({error:'Already submitted'})}});
app.get('/api/referrals',auth,(req,res)=>{const referrals=db.prepare('SELECT id,name,created_at FROM users WHERE referred_by=? ORDER BY id DESC').all(req.user.id);const rewards=db.prepare('SELECT rr.*,u.name referred_name FROM referral_rewards rr JOIN users u ON u.id=rr.referred_user_id WHERE rr.referrer_id=? ORDER BY rr.id DESC').all(req.user.id);const signupRewards=db.prepare('SELECT rs.*,u.name referred_name FROM referral_signup_rewards rs JOIN users u ON u.id=rs.referred_user_id WHERE rs.referrer_id=? ORDER BY rs.id DESC').all(req.user.id);const totalRewards=rewards.filter(x=>x.status==='credited').reduce((a,x)=>a+Number(x.amount),0)+signupRewards.filter(x=>x.status==='credited').reduce((a,x)=>a+Number(x.referrer_amount),0);res.json({referrals,rewards,signupRewards,total:totalRewards,signupBonusPerReferral:25,newUserWelcomeBonus:80})});

