app.post('/api/advertiser/register',async(req,res)=>{const{businessName,ownerName,email,password}=req.body||{};if(!businessName||!ownerName||!email||!password||password.length<6)return res.status(400).json({error:'Complete business details and 6+ character password required'});try{const h=await bcrypt.hash(password,12);const r=db.prepare('INSERT INTO advertisers(business_name,owner_name,email,password_hash) VALUES(?,?,?,?)').run(String(businessName).trim(),String(ownerName).trim(),cleanEmail(email),h);const a=db.prepare('SELECT id,business_name,owner_name,email,balance,status FROM advertisers WHERE id=?').get(r.lastInsertRowid);res.status(201).json({advertiser:a,token:sign({id:a.id,email:a.email,role:'advertiser'})})}catch{res.status(409).json({error:'Business email already registered'})}});
