app.post('/api/admin/deposits/:id/approve',adminAuth,(req,res)=>{const d=db.prepare('SELECT * FROM deposits WHERE id=?').get(req.params.id);if(!d||d.status!=='pending')return res.status(400).json({error:'Deposit is not pending'});db.transaction(()=>{db.prepare("UPDATE deposits SET status='approved',admin_note=?,verified_at=CURRENT_TIMESTAMP WHERE id=?").run(req.body?.note||'Verified',d.id);addUserLedger(d.user_id,'deposit',d.id,d.amount,'credit','Verified Send Money payment');audit(req.admin.id,'approve_deposit','deposit',d.id,`amount=${d.amount}`)})();res.json({message:'Deposit approved and wallet credited'})});
app.post('/api/admin/deposits/:id/reject',adminAuth,(req,res)=>{const d=db.prepare('SELECT * FROM deposits WHERE id=?').get(req.params.id);if(!d||d.status!=='pending')return res.status(400).json({error:'Deposit is not pending'});db.prepare("UPDATE deposits SET status='rejected',admin_note=?,verified_at=CURRENT_TIMESTAMP WHERE id=?").run(req.body?.note||'Could not verify',d.id);audit(req.admin.id,'reject_deposit','deposit',d.id,req.body?.note||'');res.json({message:'Deposit rejected'})});
app.get('/api/admin/advertiser-deposits',adminAuth,(req,res)=>res.json(db.prepare('SELECT d.*,a.business_name,a.email FROM advertiser_deposits d JOIN advertisers a ON a.id=d.advertiser_id ORDER BY d.id DESC LIMIT 500').all()));
app.post('/api/admin/advertiser-deposits/:id/approve',adminAuth,(req,res)=>{const d=db.prepare('SELECT * FROM advertiser_deposits WHERE id=?').get(req.params.id);if(!d||d.status!=='pending')return res.status(400).json({error:'Funding is not pending'});db.transaction(()=>{db.prepare("UPDATE advertiser_deposits SET status='approved',admin_note=?,verified_at=CURRENT_TIMESTAMP WHERE id=?").run(req.body?.note||'Verified',d.id);addAdvertiserLedger(d.advertiser_id,'deposit',d.id,d.amount,'credit','Verified business funding');audit(req.admin.id,'approve_business_funding','advertiser_deposit',d.id,`amount=${d.amount}`)})();res.json({message:'Business funding approved'})});
app.post('/api/admin/advertiser-deposits/:id/reject',adminAuth,(req,res)=>{const d=db.prepare('SELECT * FROM advertiser_deposits WHERE id=?').get(req.params.id);if(!d||d.status!=='pending')return res.status(400).json({error:'Funding is not pending'});db.prepare("UPDATE advertiser_deposits SET status='rejected',admin_note=?,verified_at=CURRENT_TIMESTAMP WHERE id=?").run(req.body?.note||'Could not verify',d.id);audit(req.admin.id,'reject_business_funding','advertiser_deposit',d.id,req.body?.note||'');res.json({message:'Rejected'})});

// Campaigns/tasks
app.get('/api/admin/campaigns',adminAuth,(req,res)=>res.json(db.prepare('SELECT c.*,a.business_name,a.email FROM campaigns c JOIN advertisers a ON a.id=c.advertiser_id ORDER BY c.id DESC LIMIT 500').all()));
app.post('/api/admin/campaigns/:id/approve',adminAuth,(req,res)=>{const c=db.prepare('SELECT * FROM campaigns WHERE id=?').get(req.params.id);if(!c||c.status!=='pending')return res.status(400).json({error:'Campaign is not pending'});const a=db.prepare('SELECT balance,status FROM advertisers WHERE id=?').get(c.advertiser_id);if(!a||a.status!=='active')return res.status(400).json({error:'Advertiser is not active'});if(a.balance<c.total_budget)return res.status(400).json({error:'Advertiser balance is insufficient'});if(Math.floor((c.total_budget-c.platform_fee)/c.reward_per_completion)<1)return res.status(400).json({error:'Budget is below one completion reward'});db.transaction(()=>{addAdvertiserLedger(c.advertiser_id,'campaign_reserve',c.id,c.total_budget,'debit','Campaign budget reserved');db.prepare("UPDATE campaigns SET status='approved',remaining_budget=? WHERE id=?").run(c.total_budget-c.platform_fee,c.id);const t=db.prepare("INSERT INTO tasks(title,description,category,reward,task_type) VALUES(?,?,?,?,?)").run(c.title,c.description,c.category,c.reward_per_completion,'business');db.prepare('INSERT INTO campaign_tasks(campaign_id,task_id) VALUES(?,?)').run(c.id,t.lastInsertRowid);audit(req.admin.id,'approve_campaign','campaign',c.id,`task=${t.lastInsertRowid}`)})();res.json({message:'Campaign approved and task published'})});
app.post('/api/admin/campaigns/:id/reject',adminAuth,(req,res)=>{const c=db.prepare('SELECT * FROM campaigns WHERE id=?').get(req.params.id);if(!c||c.status!=='pending')return res.status(400).json({error:'Campaign is not pending'});db.prepare("UPDATE campaigns SET status='rejected' WHERE id=?").run(c.id);audit(req.admin.id,'reject_campaign','campaign',c.id,req.body?.note||'');res.json({message:'Campaign rejected'})});
app.get('/api/admin/tasks',adminAuth,(req,res)=>res.json(db.prepare('SELECT * FROM tasks ORDER BY id DESC LIMIT 500').all()));
app.post('/api/admin/tasks',adminAuth,(req,res)=>{const{title,description,category,reward,taskType='public'}=req.body||{};if(!title||!description||!category||!validAmount(Number(reward))||!['public','business'].includes(taskType))return res.status(400).json({error:'Invalid task'});const r=db.prepare('INSERT INTO tasks(title,description,category,reward,task_type) VALUES(?,?,?,?,?)').run(String(title).trim(),String(description).trim(),String(category).trim(),Number(reward),taskType);audit(req.admin.id,'create_task','task',Number(r.lastInsertRowid),`${taskType}:${String(title).trim()}`);res.status(201).json({id:r.lastInsertRowid,taskType})});
app.post('/api/admin/tasks/:id/status',adminAuth,(req,res)=>{const status=String(req.body?.status||'');if(!['active','paused','closed'].includes(status))return res.status(400).json({error:'Invalid task status'});db.prepare('UPDATE tasks SET status=? WHERE id=?').run(status,req.params.id);audit(req.admin.id,'task_status','task',Number(req.params.id),status);res.json({message:'Task status updated'})});

// Submission review / rewards
app.get('/api/admin/task-submissions',adminAuth,(req,res)=>res.json(db.prepare('SELECT s.*,u.name,u.email,t.title,t.category FROM task_submissions s JOIN users u ON u.id=s.user_id JOIN tasks t ON t.id=s.task_id ORDER BY s.id DESC LIMIT 500').all()));
app.post('/api/admin/task-submissions/:id/approve',adminAuth,(req,res)=>{const s=db.prepare('SELECT s.*,u.referred_by,t.title FROM task_submissions s JOIN users u ON u.id=s.user_id JOIN tasks t ON t.id=s.task_id WHERE s.id=?').get(req.params.id);if(!s||s.status!=='pending')return res.status(400).json({error:'Submission is not pending'});const campaign=db.prepare("SELECT c.* FROM campaigns c JOIN campaign_tasks ct ON ct.campaign_id=c.id WHERE ct.task_id=? AND c.status='approved'").get(s.task_id);if(campaign&&campaign.remaining_budget<s.reward)return res.status(400).json({error:'Campaign reward budget is exhausted'});const referralRate=.05;db.transaction(()=>{db.prepare("UPDATE task_submissions SET status='approved',admin_note=?,verified_at=CURRENT_TIMESTAMP,verified_by=? WHERE id=?").run(req.body?.note||'Verified',req.admin.email,s.id);if(campaign)db.prepare('UPDATE campaigns SET remaining_budget=remaining_budget-? WHERE id=?').run(s.reward,campaign.id);addUserLedger(s.user_id,'task',s.id,s.reward,'credit',campaign?'Verified advertiser campaign reward':'Verified platform task reward');db.prepare('INSERT INTO earnings(user_id,type,source_id,amount,description) VALUES(?,?,?,?,?)').run(s.user_id,'task',s.id,s.reward,campaign?'Verified advertiser campaign reward':'Verified platform task reward');if(s.referred_by){const rr=Math.round(s.reward*referralRate*100)/100;if(rr>0){addUserLedger(s.referred_by,'referral',s.id,rr,'credit','5% qualifying activity referral reward');db.prepare('INSERT INTO referral_rewards(referrer_id,referred_user_id,source_submission_id,amount) VALUES(?,?,?,?)').run(s.referred_by,s.user_id,s.id,rr);db.prepare('INSERT INTO earnings(user_id,type,source_id,amount,description) VALUES(?,?,?,?,?)').run(s.referred_by,'referral',s.id,rr,'5% qualifying activity referral reward')}}audit(req.admin.id,'approve_task_submission','task_submission',s.id,`reward=${s.reward}`)})();res.json({message:'Task approved and reward credited'})});
app.post('/api/admin/task-submissions/:id/reject',adminAuth,(req,res)=>{const s=db.prepare('SELECT * FROM task_submissions WHERE id=?').get(req.params.id);if(!s||s.status!=='pending')return res.status(400).json({error:'Submission is not pending'});db.prepare("UPDATE task_submissions SET status='rejected',admin_note=?,verified_at=CURRENT_TIMESTAMP,verified_by=? WHERE id=?").run(req.body?.note||'Proof not sufficient',req.admin.email,s.id);audit(req.admin.id,'reject_task_submission','task_submission',s.id,req.body?.note||'');res.json({message:'Task rejected'})});

// Withdrawals
app.get('/api/admin/withdrawals',adminAuth,(req,res)=>res.json(db.prepare('SELECT w.*,u.name,u.email FROM withdrawals w JOIN users u ON u.id=w.user_id ORDER BY w.id DESC LIMIT 500').all()));
app.post('/api/admin/withdrawals/:id/complete',adminAuth,(req,res)=>{const w=db.prepare('SELECT * FROM withdrawals WHERE id=?').get(req.params.id);const tx=String(req.body?.transactionId||'').trim();if(!w||w.status!=='pending')return res.status(400).json({error:'Withdrawal is not pending'});if(tx.length<4)return res.status(400).json({error:'Agent payout transaction ID required'});if(db.prepare('SELECT id FROM withdrawals WHERE transaction_id=?').get(tx))return res.status(409).json({error:'This payout transaction ID is already recorded'});db.prepare("UPDATE withdrawals SET status='completed',transaction_id=?,admin_note=?,completed_at=CURRENT_TIMESTAMP WHERE id=?").run(tx,req.body?.note||'Paid by agent',w.id);audit(req.admin.id,'complete_withdrawal','withdrawal',w.id,`tx=${tx}`);res.json({message:'Withdrawal completed'})});
app.post('/api/admin/withdrawals/:id/reject',adminAuth,(req,res)=>{const w=db.prepare('SELECT * FROM withdrawals WHERE id=?').get(req.params.id);if(!w||w.status!=='pending')return res.status(400).json({error:'Withdrawal is not pending'});db.transaction(()=>{db.prepare("UPDATE withdrawals SET status='rejected',admin_note=? WHERE id=?").run(req.body?.note||'Rejected',w.id);addUserLedger(w.user_id,'withdrawal_reversal',w.id,w.amount,'credit','Rejected withdrawal balance returned');audit(req.admin.id,'reject_withdrawal','withdrawal',w.id,req.body?.note||'')})();res.json({message:'Rejected; balance returned'})});

