const server=app.listen(PORT,'0.0.0.0',()=>console.log(`AVRIXON V14 running on port ${PORT}`));
server.requestTimeout=30000;
server.headersTimeout=35000;
server.keepAliveTimeout=5000;
function shutdown(signal){console.log(`${signal}: shutting down AVRIXON`);server.close(()=>{try{db.close()}finally{process.exit(0)}});setTimeout(()=>process.exit(1),10000).unref()}
process.on('SIGTERM',()=>shutdown('SIGTERM'));
process.on('SIGINT',()=>shutdown('SIGINT'));
app.use((err,req,res,next)=>{console.error(err);if(res.headersSent)return next(err);res.status(500).json({error:'Internal server error'})});
